// Clean-room generalized vector First Fit bin-packing profile.
const MAX_N:usize=32;const MAX_D:usize=4;const INPUT:usize=130;const FIELDS:usize=161;
fn put(out:[*]u8,at:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|i|out[at+i]=@truncate(bits>>@intCast(8*i));}
export fn vector_bin_packing(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{if(input_opt==null||length<2||length>INPUT)return -1;const input=input_opt.?;const n64=input[0];const d64=input[1];if(n64<1||n64>32||d64<1||d64>4||length!=2+@as(usize,@intCast(n64*d64)))return -1;const n:usize=@intCast(n64);const d:usize=@intCast(d64);for(0..n*d)|i|if(input[2+i]<0||input[2+i]>1000)return -1;var loads:[MAX_N*MAX_D]i64=@splat(0);var assignment:[MAX_N]usize=@splat(0);var bins:usize=0;for(0..n)|item|{var chosen=bins;for(0..bins)|b|{var fits=true;for(0..d)|q|if(loads[b*MAX_D+q]+input[2+item*d+q]>1000){fits=false;};if(fits){chosen=b;break;}}if(chosen==bins)bins+=1;assignment[item]=chosen;for(0..d)|q|loads[chosen*MAX_D+q]+=input[2+item*d+q];}var staged:[FIELDS]i64=@splat(0);var count:usize=0;staged[count]=@intCast(bins);count+=1;for(0..n)|i|{staged[count]=@intCast(assignment[i]);count+=1;}for(0..bins)|b|{for(0..d)|q|{staged[count]=loads[b*MAX_D+q];count+=1;}}if(output_opt==null||capacity<8*count)return -2;const output=output_opt.?;for(0..count)|i|put(output,8*i,staged[i]);return @intCast(8*count);}
